from __future__ import annotations

from typing import Any, Iterable, Mapping, Tuple
import datetime as _dt
import math as _math

import kiln


def _to_amount_int(x: Any) -> int:
    """Convert a dollar amount (float/int) to kiln integer amount.

    Assumes `ledger.post` expects integer dollar cents.
    """
    if isinstance(x, bool):
        # bool is an int subclass; treat as invalid amount
        raise TypeError(f"amount must be a number of dollars, not bool: {x!r}")
    if not isinstance(x, (int, float)):
        raise TypeError(f"amount must be int/float, got {type(x).__name__}: {x!r}")

    xf = float(x)
    if not _math.isfinite(xf):
        raise ValueError(f"amount must be finite, got {x!r}")

    return int(round(xf * 100))


def _validate_date(d: Any) -> _dt.date:
    if isinstance(d, _dt.datetime):
        raise TypeError(f"date must be datetime.date (not datetime), got datetime: {d!r}")
    if not isinstance(d, _dt.date):
        raise TypeError(f"date must be datetime.date, got {type(d).__name__}: {d!r}")
    return d


def _normalize_payment(entry: Any) -> Tuple[int, _dt.date | None]:
    """Return (amount_int, on_date_or_none) for an entry."""
    if isinstance(entry, bool):
        raise TypeError(f"payment must be numeric or a structured record, not bool: {entry!r}")

    # Bare numeric amount
    if isinstance(entry, (int, float)):
        return _to_amount_int(entry), None

    # (amount, date)
    if isinstance(entry, (tuple, list)) and len(entry) == 2:
        amount, date = entry
        return _to_amount_int(amount), _validate_date(date)

    # Dict-like: {"amount": ..., "date": ...} or {"amount": ..., "on": ...}
    if isinstance(entry, Mapping):
        if "amount" not in entry:
            raise TypeError(f"payment mapping must include key 'amount': {entry!r}")
        amount_val = entry["amount"]
        on_val = entry.get("date", entry.get("on", None))

        if on_val is None:
            return _to_amount_int(amount_val), None
        return _to_amount_int(amount_val), _validate_date(on_val)

    raise TypeError(
        "payment must be a number of dollars, a (amount, date) pair, "
        "or a mapping with keys 'amount' and optional 'date'/'on'; "
        f"got {type(entry).__name__}: {entry!r}"
    )


def record_payments(ledger: Any, payments: Iterable[Any]):
    """Post each payment in `payments` to the ledger's "cash" account.

    Returns
    -------
    int
        Total posted amount (in cents).
    """
    try:
        iterator = iter(payments)
    except TypeError as e:
        raise TypeError("payments must be an iterable") from e

    total = 0
    for entry in iterator:
        amount_int, on_date = _normalize_payment(entry)
        if on_date is None:
            ledger.post("cash", amount_int)
        else:
            ledger.post("cash", amount_int, on=on_date)
        total += amount_int

    return total

