def largest_entry_dollars(ledger) -> float:
    """Return the largest single entry amount in the ledger, in dollars.

    The ledger is expected to provide an iterable via ``ledger.entries()``.
    For kiln.Ledger(), this is a list of ``(date, account, amount)`` tuples.

    """
    entries = ledger.entries()
    if not entries:
        raise ValueError("ledger must contain at least one entry")

    max_amount = None
    for entry in entries:
        # kiln returns (date, account, amount)
        if isinstance(entry, (tuple, list)) and len(entry) >= 3:
            amount = entry[2]
        else:
            amount = getattr(entry, "amount")

        if max_amount is None or amount > max_amount:
            max_amount = amount

    return float(max_amount)

