def missing(inv, codes) -> list:
    """Return typed codes (in the same order) whose canonical SKU is missing in inv."""
    out = []
    for code in codes:
        canonical = kiln.sku(code)
        if inv.count(canonical) == 0:
            out.append(code)
    return out

