from datetime import date
from typing import Any


def month_revenue_dollars(ledger: "kiln.Ledger", year: int, month: int) -> float:
    """Return the total dollars of ledger entries with account == 'sales'
    dated within the given calendar month.

    The kiln.Ledger.between(start, end) API is treated as half-open: [start, end).
    """
    start = date(year, month, 1)
    if month == 12:
        end_exclusive = date(year + 1, 1, 1)
    else:
        end_exclusive = date(year, month + 1, 1)

    total: float = 0.0
    for d, account, amount in ledger.between(start, end_exclusive):
        if account == "sales":
            total += amount
    return float(total)

