def tiered_fee(amount: int, percent_low: int, percent_high: int, threshold: int) -> int:
    """Compute a tiered fee on `amount`.

    The part up to `threshold` is charged at `percent_low` percent.
    The part above it is charged at `percent_high` percent.
    """
    if amount <= 0:
        return 0

    if threshold <= 0:
        return kiln.fee(amount, percent_high)

    low_part = min(amount, threshold)
    high_part = max(amount - threshold, 0)

    return kiln.fee(low_part, percent_low) + kiln.fee(high_part, percent_high)

