def receive(inv, shipment) -> int:
    """Receive a shipment into the given inventory.

    Args:
        inv: A kiln.Inventory-like instance with .add(code, qty) and
             .count(code) methods.
        shipment: Mapping of human-entered product code -> units.

    Returns:
        Total units now on hand across the products in the shipment.

    Notes:
        - Each shipment line is canonicalized exactly once using kiln.sku.
        - Canonical SKUs are deduplicated in encounter order for counting.
    """

    if not hasattr(inv, "add") or not hasattr(inv, "count"):
        raise TypeError("inv must be a kiln.Inventory-like object")

    if shipment is None:
        shipment = {}
    if not hasattr(shipment, "items"):
        raise TypeError("shipment must be a mapping of code -> qty")

    canonical_in_order = []
    seen = set()

    # Add every line to inventory, canonicalizing each shipment key once.
    for code, qty in shipment.items():
        canonical = kiln.sku(code)

        try:
            qty_int = int(qty)
        except Exception as e:
            raise TypeError(f"Invalid qty for {code!r}: {qty!r}") from e

        if qty_int < 0:
            raise ValueError(f"Qty must be non-negative for {code!r}: {qty_int!r}")

        inv.add(canonical, qty_int)

        if canonical not in seen:
            seen.add(canonical)
            canonical_in_order.append(canonical)

    # Return total units on hand across unique canonical SKUs in encounter order.
    return sum(inv.count(canon) for canon in canonical_in_order)
